static String toBin8(int octet) {
    String s = Integer.toBinaryString(octet & 0xFF);
    return "0".repeat(8 - s.length()) + s;
}
// alternatywa: String.format("%8s", Integer.toBinaryString(octet & 0xFF)).replace(' ', '0')

static int fromBin(String s) {
    return Integer.parseInt(s, 2);
}

